// ============================================================================
// ⚙️ MASTER CONFIGURATION — EDIT YOUR KEYS HERE (OR USE DOCKER ENV VARS)
// ============================================================================
const env = (typeof $env !== 'undefined' && $env) ? $env : {};
const cleanEnv = (val, fallback) => {
  const s = String(val || '').trim();
  if (!s || s.startsWith('PASTE_YOUR_') || s.includes('REDACTED') || s === ('5365' + '295465')) {
    return fallback;
  }
  return s;
};

const CONFIG = {
  // 1. Local n8n API Settings (Settings -> n8n API -> Create an API Key)
  N8N_BASE_URL: cleanEnv(env.N8N_BASE_URL, 'http://localhost:5678').replace(/\/+$/, ''),
  N8N_PUBLIC_URL: cleanEnv(env.WEBHOOK_URL, env.N8N_HOST ? 'https://' + env.N8N_HOST : 'http://localhost:11434').replace(/\/+$/, ''),
  N8N_API_KEY: cleanEnv(env.N8N_API_KEY, 'YOUR_N8N_JWT_API_KEY'),

  // 2. Telegram Bot Settings (@BotFather token & your numeric Telegram Chat ID)
  TELEGRAM_BOT_TOKEN: cleanEnv(env.TELEGRAM_BOT_TOKEN, 'YOUR_TELEGRAM_BOT_TOKEN'),
  ADMIN_CHAT_ID: String(cleanEnv(env.ADMIN_CHAT_ID, '8873019272')).replace(/^=/, ''),

  // 3. Google Gemini Flash API Key (Free at https://aistudio.google.com/apikey)
  //    Uses 0% CPU/RAM on your Hostinger KVM2. Automatically falls back to
  //    local Ollama or built-in diagnostics if left blank.
  GEMINI_API_KEY: cleanEnv(env.GEMINI_API_KEY, 'YOUR_GEMINI_API_KEY'),
  GEMINI_MODEL: cleanEnv(env.GEMINI_MODEL, 'gemini-2.5-flash'),
  OLLAMA_FALLBACK_URL: cleanEnv(env.OLLAMA_FALLBACK_URL, 'http://localhost:11434/api/generate'),
  OLLAMA_FALLBACK_MODEL: cleanEnv(env.OLLAMA_FALLBACK_MODEL, 'qwen3:1.7b'),

  // 4. GitHub Daily Backup Settings (Fine-grained PAT with "Contents: Read & Write")
  GITHUB_TOKEN: cleanEnv(env.GITHUB_TOKEN, 'YOUR_GITHUB_TOKEN'),
  GITHUB_REPO: env.GITHUB_REPO || 'banerjee08/n8n-workflows',
  GITHUB_BRANCH: env.GITHUB_BRANCH || 'main',
  BACKUP_BASE_DIR: env.BACKUP_BASE_DIR || 'workflows',

  // 5. Concurrency, Pipeline Queue & Schedule Advisor Settings (Hostinger KVM2)
  MAX_CONCURRENT_WORKFLOWS: Number(env.MAX_CONCURRENT_WORKFLOWS || 1),
  MAX_EXECUTION_TIMEOUT_MINS: Number(env.MAX_EXECUTION_TIMEOUT_MINS || 45), // Auto-kills hung zombie runs > 45m
  AUTO_SHIFT_OVERLAPPING_SCHEDULES: true, // Automatically shifts Schedule Trigger time on overlap!
  TIMEZONE_OFFSET_MINUTES: 330, // IST (UTC+5:30 = +330 mins)
  TIMEZONE_LABEL: 'IST',
  PAGE_SIZE: 8,
  AUTO_WIRE_ON_BACKUP: true,
  MASTER_WORKFLOW_ID: $workflow.id,
  MASTER_WORKFLOW_NAME: $workflow.name,
  CURRENT_EXECUTION_ID: $execution.id
};

// Detect which of the 4 Triggers activated this execution
const rawItem = $input.first()?.json || {};
const item = (rawItem.body && (rawItem.body.message || rawItem.body.callback_query || rawItem.body.update_id)) ? rawItem.body : rawItem;
let eventType = 'watchdog';

if (item.execution && item.workflow) {
  eventType = 'error';
} else if (item.message || item.callback_query) {
  const rawText = (item.message?.text || '').trim();
  const cbData = (item.callback_query?.data || '').trim();
  if (rawText === '/backup' || rawText.startsWith('/backup@') || cbData === 'cmd:backup') {
    eventType = 'backup';
  } else {
    eventType = 'telegram';
  }
} else {
  // Check if triggered manually via 'When clicking Execute workflow' in n8n UI
  let firedManually = false;
  try {
    if ($("When clicking 'Execute workflow'").isExecuted) {
      firedManually = true;
    }
  } catch (e) {}
  if (firedManually) {
    eventType = 'telegram';
    item.message = {
      chat: { id: CONFIG.ADMIN_CHAT_ID },
      text: '/menu'
    };
  } else {
    // Distinguish Daily Backup Schedule (18:30 UTC / 00:00 IST) vs 1-Minute Overlap Watchdog
    let firedByBackupSchedule = false;
    try {
      if ($('Daily Backup Schedule (00:00 IST)').isExecuted) {
        firedByBackupSchedule = true;
      }
    } catch (e) {}
    eventType = firedByBackupSchedule ? 'backup' : 'watchdog';
  }
}

return [{
  json: {
    ...item,
    _eventType: eventType,
    _config: CONFIG
  }
}];

// ============================================================================
// 📱 LANE 1: TELEGRAM CONTROLLER, CONCURRENCY PIPELINE & SCHEDULE ADVISOR
// ============================================================================
const payload = $input.first().json;
const cfg = payload._config;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.pipelineQueue)) staticData.pipelineQueue = [];
if (!staticData.intentionallyStoppedExecs) staticData.intentionallyStoppedExecs = {};
if (!staticData.lastPausedGroup) staticData.lastPausedGroup = {};

// Universal HTTP helper
async function apiRequest(ctx, opts) {
  if (ctx && ctx.helpers && typeof ctx.helpers.httpRequest === 'function') {
    return await ctx.helpers.httpRequest({
      method: opts.method || 'GET',
      url: opts.url,
      headers: opts.headers || {},
      body: opts.body,
      json: true,
    });
  }
  const fetchOpts = {
    method: opts.method || 'GET',
    headers: {
      'Accept': 'application/json',
      ...(opts.body ? { 'Content-Type': 'application/json' } : {}),
      ...(opts.headers || {}),
    },
  };
  if (opts.body !== undefined) {
    fetchOpts.body = typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body);
  }
  const res = await fetch(opts.url, fetchOpts);
  const text = await res.text();
  let data;
  try { data = text ? JSON.parse(text) : {}; } catch (e) { data = { raw: text }; }
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${typeof data === 'object' ? JSON.stringify(data) : text}`);
  }
  return data;
}

const n8nHeaders = { 'X-N8N-API-KEY': cfg.N8N_API_KEY };

// Extract Telegram context
const isCallback = Boolean(payload.callback_query);
const chatId = String(
  isCallback
    ? payload.callback_query?.message?.chat?.id || payload.callback_query?.from?.id
    : payload.message?.chat?.id || ''
);
const messageId = isCallback ? payload.callback_query?.message?.message_id : null;
const callbackQueryId = isCallback ? payload.callback_query?.id : null;
const text = (payload.message?.text || '').trim();
const cbData = (payload.callback_query?.data || '').trim();

// Security Gate: Only allow ADMIN_CHAT_ID
if (cfg.ADMIN_CHAT_ID && cfg.ADMIN_CHAT_ID !== 'YOUR_TELEGRAM_CHAT_ID' && chatId !== String(cfg.ADMIN_CHAT_ID)) {
  return [{
    json: {
      _config: cfg,
      chatId,
      shouldExecuteSubworkflow: false,
      telegramResponse: {
        text: `⛔ *Unauthorized Access*\nYour Chat ID (\`${chatId}\`) is not authorized to control this n8n instance.`,
        parseMode: 'Markdown'
      }
    }
  }];
}

// Helper: Auto-wire a single workflow
async function autoWireWorkflow(wfSummaryOrFull) {
  const wf = wfSummaryOrFull.nodes
    ? wfSummaryOrFull
    : await apiRequest(this, {
        method: 'GET',
        url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wfSummaryOrFull.id}`,
        headers: n8nHeaders,
      });

  if (String(wf.id) === String(cfg.MASTER_WORKFLOW_ID)) {
    return { changed: false, wf };
  }

  let changed = false;
  const nodes = Array.isArray(wf.nodes) ? [...wf.nodes] : [];
  const connections = wf.connections ? JSON.parse(JSON.stringify(wf.connections)) : {};
  const settings = wf.settings ? { ...wf.settings } : { executionOrder: 'v1' };

  if (cfg.MASTER_WORKFLOW_ID && settings.errorWorkflow !== cfg.MASTER_WORKFLOW_ID) {
    settings.errorWorkflow = cfg.MASTER_WORKFLOW_ID;
    changed = true;
  }
  if (settings.saveExecutionProgress !== true) {
    settings.saveExecutionProgress = true;
    changed = true;
  }

  const hasSubTrigger = nodes.some(n => n.type === 'n8n-nodes-base.executeWorkflowTrigger');
  if (!hasSubTrigger) {
    const primaryTrigger = nodes.find(n =>
      n.type === 'n8n-nodes-base.scheduleTrigger' ||
      n.type === 'n8n-nodes-base.manualTrigger' ||
      n.type.toLowerCase().includes('trigger')
    );

    const triggerName = 'On-Demand Telegram Trigger';
    const pos = primaryTrigger?.position ? [primaryTrigger.position[0], primaryTrigger.position[1] + 180] : [0, 180];

    nodes.push({
      parameters: { inputSource: 'passthrough' },
      id: 'ondemand-tg-trigger-' + String(wf.id).slice(0, 8),
      name: triggerName,
      type: 'n8n-nodes-base.executeWorkflowTrigger',
      typeVersion: 1.1,
      position: pos
    });

    if (primaryTrigger && connections[primaryTrigger.name]) {
      connections[triggerName] = JSON.parse(JSON.stringify(connections[primaryTrigger.name]));
    }
    changed = true;
  }

  if (changed) {
    let updated = await apiRequest(this, {
      method: 'PUT',
      url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}`,
      headers: n8nHeaders,
      body: {
        name: wf.name,
        nodes,
        connections,
        settings,
        ...(wf.staticData ? { staticData: wf.staticData } : {})
      }
    });
    if (wf.active) {
      try {
        await apiRequest(this, {
          method: 'POST',
          url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}/deactivate`,
          headers: n8nHeaders
        });
      } catch (e) {}
      try {
        updated = await apiRequest(this, {
          method: 'POST',
          url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}/activate`,
          headers: n8nHeaders
        });
      } catch (e) {}
    }
    return { changed: true, wf: updated };
  }

  return { changed: false, wf };
}

// Helper: Fetch all workflows + running worker executions + recent execution history
async function fetchAllState(includeHistory = false) {
  const wfRes = await apiRequest(this, {
    method: 'GET',
    url: `${cfg.N8N_BASE_URL}/api/v1/workflows?limit=250`,
    headers: n8nHeaders
  });
  let runningExecs = [];
  try {
    const execRes = await apiRequest(this, {
      method: 'GET',
      url: `${cfg.N8N_BASE_URL}/api/v1/executions?status=running&limit=100`,
      headers: n8nHeaders
    });
    // Exclude this Master Manager's own execution from worker count
    runningExecs = (execRes.data || []).filter(
      e => String(e.workflowId) !== String(cfg.MASTER_WORKFLOW_ID) && String(e.id) !== String(cfg.CURRENT_EXECUTION_ID)
    );
  } catch (e) {
    runningExecs = [];
  }
  let recentExecs = [];
  if (includeHistory) {
    try {
      const histRes = await apiRequest(this, {
        method: 'GET',
        url: `${cfg.N8N_BASE_URL}/api/v1/executions?limit=150`,
        headers: n8nHeaders
      });
      recentExecs = histRes.data || [];
    } catch (e) {
      recentExecs = [];
    }
  }
  const allWorkflows = (wfRes.data || []).filter(w => !w.isArchived);
  return { allWorkflows, runningExecs, recentExecs };
}

// ============================================================================
// 🗓️ SMART SCHEDULE ANALYZER, FREE HOURS FINDER & AUTO-STAGGER ENGINE
// ============================================================================
function analyzeWorkflowSchedule(wf, avgDurationMins) {
  const nodes = wf.nodes || [];
  const schedNodes = nodes.filter(n => n.type === 'n8n-nodes-base.scheduleTrigger');
  // Estimate CPU/RAM weight on Hostinger KVM2
  const nodeTypesAndUrls = nodes.map(n => `${n.type || ""} ${n.parameters?.url || ""}`).join(" ").toLowerCase();
  let weight = '🟢 Light';
  let loadScore = 1;
  if (nodeTypesAndUrls.includes('ollama') || nodeTypesAndUrls.includes('11434') || nodeTypesAndUrls.includes('gotenberg') || nodeTypesAndUrls.includes('puppeteer')) {
    weight = '🔴 Heavy (LLM/Browser)';
    loadScore = 3;
  } else if (nodeTypesAndUrls.includes('googlesheets') || nodeTypesAndUrls.includes('supabase') || nodeTypesAndUrls.includes('printify')) {
    weight = '🟡 Medium (API/DB Sync)';
    loadScore = 2;
  }

  if (schedNodes.length === 0) {
    return { hasSchedule: false, weight, loadScore, summary: 'On-Demand / Event Only', occupiedHoursIST: [], triggerMinute: 0 };
  }

  const occupiedHours = new Set();
  let triggerMinute = 0;
  const summaries = [];

  for (const sn of schedNodes) {
    const intervals = sn.parameters?.rule?.interval || [{}];
    for (const rule of intervals) {
      const field = rule.field || 'hours';
      if (field === 'cronExpression') {
        const expr = (rule.expression || '0 * * * *').trim();
        const parts = expr.split(/\s+/);
        const minPart = parseInt(parts[0], 10);
        const hrPart = parts[1];
        if (!isNaN(minPart)) triggerMinute = minPart;
        if (hrPart === '*') {
          for (let h = 0; h < 24; h++) occupiedHours.add(h);
          summaries.push(`Every hour at :${String(triggerMinute || 0).padStart(2, '0')} (Cron: \`${expr}\`)`);
        } else {
          const utcHours = hrPart.split(',').map(x => parseInt(x, 10)).filter(x => !isNaN(x));
          for (const uh of utcHours) {
            const totalIstMins = (uh * 60 + (triggerMinute || 0) + cfg.TIMEZONE_OFFSET_MINUTES) % 1440;
            const istHour = Math.floor(totalIstMins / 60);
            occupiedHours.add(istHour);
          }
          summaries.push(`Cron \`${expr}\``);
        }
      } else if (field === 'minutes') {
        const mInt = Number(rule.minutesInterval || 30);
        for (let h = 0; h < 24; h++) occupiedHours.add(h);
        triggerMinute = 0;
        summaries.push(`Every ${mInt} mins`);
      } else if (field === 'hours') {
        const hInt = Math.max(1, Number(rule.hoursInterval || 1));
        triggerMinute = Number(rule.triggerAtMinute || 0);
        for (let h = 0; h < 24; h += hInt) {
          occupiedHours.add(h);
        }
        summaries.push(`Every ${hInt}h at :${String(triggerMinute).padStart(2, '0')}`);
      } else if (field === 'days' || field === 'weeks') {
        const h = Number(rule.triggerAtHour || 0);
        triggerMinute = Number(rule.triggerAtMinute || 0);
        occupiedHours.add(h);
        summaries.push(`Daily at ${String(h).padStart(2, '0')}:${String(triggerMinute).padStart(2, '0')}`);
      } else {
        for (let h = 0; h < 24; h++) occupiedHours.add(h);
        summaries.push(`Frequent (${field})`);
      }
    }
  }

  return {
    hasSchedule: true,
    weight,
    loadScore,
    avgDurationMins,
    triggerMinute,
    summary: summaries.join(', '),
    occupiedHoursIST: Array.from(occupiedHours).sort((a, b) => a - b)
  };
}

function buildScheduleAdvisorReport(allWorkflows, recentExecs, bannerMsg = '') {
  const durationByWf = {};
  for (const ex of recentExecs) {
    if (ex.startedAt && ex.stoppedAt) {
      const durMins = Math.max(0.5, (new Date(ex.stoppedAt) - new Date(ex.startedAt)) / 60000);
      if (!durationByWf[ex.workflowId]) durationByWf[ex.workflowId] = [];
      durationByWf[ex.workflowId].push(durMins);
    }
  }

  const hourBuckets = Array.from({ length: 24 }, (_, h) => ({
    hour: h,
    workflows: [],
    loadScore: 0,
    totalRuntimeMins: 0
  }));

  const scheduledWfDetails = [];
  const minuteCollisions = {};

  for (const wf of allWorkflows) {
    if (String(wf.id) === String(cfg.MASTER_WORKFLOW_ID)) continue;
    const durs = durationByWf[wf.id] || [2.5];
    const avgDur = Math.round((durs.reduce((a, b) => a + b, 0) / durs.length) * 10) / 10;
    const info = analyzeWorkflowSchedule(wf, avgDur);

    if (info.hasSchedule) {
      scheduledWfDetails.push({ wf, info });
      if (wf.active) {
        for (const h of info.occupiedHoursIST) {
          hourBuckets[h].workflows.push({ name: wf.name, min: info.triggerMinute, avgDur, weight: info.weight });
          hourBuckets[h].loadScore += info.loadScore;
          hourBuckets[h].totalRuntimeMins += avgDur;
          const slotKey = `${String(h).padStart(2, '0')}:${String(info.triggerMinute).padStart(2, '0')}`;
          if (!minuteCollisions[slotKey]) minuteCollisions[slotKey] = [];
          minuteCollisions[slotKey].push(wf.name);
        }
      }
    }
  }

  const completelyFreeHours = hourBuckets
    .filter(b => b.workflows.length === 0)
    .map(b => `${String(b.hour).padStart(2, '0')}:00`);

  const rankedBestSlots = [...hourBuckets]
    .sort((a, b) => (a.loadScore - b.loadScore) || (a.totalRuntimeMins - b.totalRuntimeMins))
    .slice(0, 4)
    .map((b, idx) => {
      const usedMins = new Set(b.workflows.map(w => w.min));
      const candidateMins = [15, 45, 20, 40, 10, 50];
      const bestMin = candidateMins.find(m => !usedMins.has(m)) || 15;
      const hStr = String(b.hour).padStart(2, '0');
      const mStr = String(bestMin).padStart(2, '0');
      return `• *Slot #${idx + 1}:* \`${hStr}:${mStr} ${cfg.TIMEZONE_LABEL}\` _(Load: ${b.workflows.length} active wf, Cron: \`${bestMin} ${b.hour} * * *\`)_`;
    });

  const collisionLines = [];
  for (const [slot, names] of Object.entries(minuteCollisions)) {
    if (names.length > 1) {
      collisionLines.push(`• \`${slot} ${cfg.TIMEZONE_LABEL}\`: ${names.map(n => `\`${n}\``).join(' ⚡ ')}`);
    }
  }

  const wfLines = scheduledWfDetails.map(({ wf, info }) => {
    const stateIcon = wf.active ? '🟢' : '⚪';
    return `${stateIcon} *${wf.name}*\n   └ ⏱️ ${info.summary} | ~${info.avgDurationMins}m run | ${info.weight}`;
  });

  const header = bannerMsg ? `${bannerMsg}\n\n` : '';
  const reportText =
    `${header}🗓️ *Smart Schedule Advisor & Free Hours (${cfg.TIMEZONE_LABEL})*\n` +
    `━━━━━━━━━━━━━━━━━━━━\n` +
    `📋 *Scheduled Workflows (${scheduledWfDetails.length}):*\n` +
    (wfLines.length > 0 ? wfLines.join('\n') : '_No scheduled workflows found._') +
    `\n\n` +
    `🟢 *100% Free Hours (${completelyFreeHours.length}/24 hrs with 0 scheduled runs):*\n` +
    (completelyFreeHours.length > 0
      ? `\`${completelyFreeHours.join(', ')}\``
      : `_Every hour has at least one recurring workflow (e.g. every-30m/1h sync). Use staggered minute offsets below!_`) +
    `\n\n` +
    `✨ *Best Recommended Time Slots for a New Workflow:*\n` +
    rankedBestSlots.join('\n') +
    `\n\n` +
    (collisionLines.length > 0
      ? `⚠️ *Overlapping Schedule Collisions Detected (${collisionLines.length}):*\n${collisionLines.slice(0, 5).join('\n')}\n_Tap **Auto-Stagger** below to automatically space out their start minutes!_`
      : `✅ *Zero Exact Minute Collisions* among currently active workflows!`) +
    `\n\n🚦 *Pipeline Queue:* ${staticData.pipelineQueue.length} workflow(s) waiting`;

  const keyboard = [
    [
      { text: '🪄 Auto-Stagger Overlapping Schedules', callback_data: 'cmd:stagger' }
    ],
    [
      { text: `🚦 View Pipeline Queue (${staticData.pipelineQueue.length})`, callback_data: 'cmd:queue' },
      { text: '🔄 Refresh Advisor', callback_data: 'cmd:schedule' }
    ],
    [
      { text: '📂 Schedule Drawer', callback_data: 'sec:sched' },
      { text: '▴ Back to Compact Menu', callback_data: 'nav:home' }
    ]
  ];

  return { text: reportText, inlineKeyboard: keyboard, parseMode: 'Markdown' };
}

// Helper: Auto-stagger all scheduled workflows so their start minutes don't collide
async function autoStaggerAllSchedules(allWorkflows) {
  const offsetSteps = [0, 5, 10, 3, 8, 13, 2, 7, 12, 1, 6, 11];
  let stepIdx = 0;
  const shifted = [];

  for (const wfSummary of allWorkflows) {
    if (String(wfSummary.id) === String(cfg.MASTER_WORKFLOW_ID)) continue;
    const wf = wfSummary.nodes
      ? wfSummary
      : await apiRequest(this, {
          method: 'GET',
          url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wfSummary.id}`,
          headers: n8nHeaders
        });

    let modified = false;
    const targetMin = offsetSteps[stepIdx % offsetSteps.length];
    const nodes = (wf.nodes || []).map(node => {
      if (node.type !== 'n8n-nodes-base.scheduleTrigger') return node;
      const newNode = JSON.parse(JSON.stringify(node));
      const intervals = newNode.parameters?.rule?.interval || [];
      for (const rule of intervals) {
        const field = rule.field || 'hours';
        if (field === 'hours' || field === 'days' || field === 'weeks') {
          if (Number(rule.triggerAtMinute || 0) !== targetMin) {
            rule.triggerAtMinute = targetMin;
            modified = true;
          }
        } else if (field === 'minutes') {
          const mInt = Number(rule.minutesInterval || 30);
          const mins = [];
          for (let m = targetMin % mInt; m < 60; m += mInt) mins.push(m);
          rule.field = 'cronExpression';
          rule.expression = `${mins.join(',')} * * * *`;
          delete rule.minutesInterval;
          modified = true;
        } else if (field === 'cronExpression' && rule.expression) {
          const parts = rule.expression.trim().split(/\s+/);
          if (parts.length >= 5 && /^\d+$/.test(parts[0]) && Number(parts[0]) !== targetMin) {
            parts[0] = String(targetMin);
            rule.expression = parts.join(' ');
            modified = true;
          }
        }
      }
      return newNode;
    });

    if (nodes.some(n => n.type === 'n8n-nodes-base.scheduleTrigger')) {
      stepIdx++;
    }

    if (modified) {
      await apiRequest(this, {
        method: 'PUT',
        url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}`,
        headers: n8nHeaders,
        body: {
          name: wf.name,
          nodes,
          connections: wf.connections || {},
          settings: wf.settings || { executionOrder: 'v1' },
          ...(wf.staticData ? { staticData: wf.staticData } : {})
        }
      });
      if (wf.active) {
        try {
          await apiRequest(this, {
            method: 'POST',
            url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}/deactivate`,
            headers: n8nHeaders
          });
        } catch (e) {}
        try {
          await apiRequest(this, {
            method: 'POST',
            url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}/activate`,
            headers: n8nHeaders
          });
        } catch (e) {}
      }
      shifted.push(`• \`${wf.name}\` → shifted to minute \`:${String(targetMin).padStart(2, '0')}\``);
    }
  }
  return shifted;
}

// Helper: Shift a single workflow's schedule trigger by +N minutes
async function shiftWorkflowSchedule(wfId, deltaMinutes) {
  const wf = await apiRequest(this, {
    method: 'GET',
    url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wfId}`,
    headers: n8nHeaders
  });
  let newDesc = '';
  const nodes = (wf.nodes || []).map(node => {
    if (node.type !== 'n8n-nodes-base.scheduleTrigger') return node;
    const newNode = JSON.parse(JSON.stringify(node));
    const intervals = newNode.parameters?.rule?.interval || [{}];
    for (const rule of intervals) {
      const field = rule.field || 'hours';
      if (field === 'hours' || field === 'days' || field === 'weeks') {
        const curMin = Number(rule.triggerAtMinute || 0);
        const curHr = Number(rule.triggerAtHour || 0);
        const totalMins = (curHr * 60 + curMin + deltaMinutes + 1440) % 1440;
        if (field === 'days' || field === 'weeks') {
          rule.triggerAtHour = Math.floor(totalMins / 60);
        }
        rule.triggerAtMinute = totalMins % 60;
        newDesc = `:${String(rule.triggerAtMinute).padStart(2, '0')} past the hour`;
      } else if (field === 'cronExpression' && rule.expression) {
        const parts = rule.expression.trim().split(/\s+/);
        const curMin = parseInt(parts[0], 10) || 0;
        parts[0] = String((curMin + deltaMinutes) % 60);
        rule.expression = parts.join(' ');
        newDesc = `Cron \`${rule.expression}\``;
      } else if (field === 'minutes') {
        const curInterval = Number(rule.minutesInterval || 30);
        rule.minutesInterval = Math.max(5, curInterval + deltaMinutes);
        newDesc = `Every ${rule.minutesInterval} mins`;
      }
    }
    return newNode;
  });

  let updated = await apiRequest(this, {
    method: 'PUT',
    url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}`,
    headers: n8nHeaders,
    body: {
      name: wf.name,
      nodes,
      connections: wf.connections || {},
      settings: wf.settings || { executionOrder: 'v1' },
      ...(wf.staticData ? { staticData: wf.staticData } : {})
    }
  });
  if (wf.active) {
    try {
      await apiRequest(this, {
        method: 'POST',
        url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}/deactivate`,
        headers: n8nHeaders
      });
    } catch (e) {}
    try {
      updated = await apiRequest(this, {
        method: 'POST',
        url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wf.id}/activate`,
        headers: n8nHeaders
      });
    } catch (e) {}
  }
  return { wf: updated, newDesc: newDesc || `+${deltaMinutes}m` };
}

// Helper: Build Collapsible Accordion Main Menu
function buildMainMenu(allWorkflows, runningExecs, page = 0, bannerMsg = '', openSection = 'none') {
  const sorted = [...allWorkflows].sort((a, b) => {
    if (a.active !== b.active) return a.active ? -1 : 1;
    return (a.name || '').localeCompare(b.name || '');
  });

  const pageSize = cfg.PAGE_SIZE || 8;
  const totalPages = Math.max(1, Math.ceil(sorted.length / pageSize));
  const safePage = Math.max(0, Math.min(page, totalPages - 1));
  const slice = sorted.slice(safePage * pageSize, (safePage + 1) * pageSize);

  const activeCount = sorted.filter(w => w.active).length;
  const pausedCount = sorted.length - activeCount;
  const runningByWf = {};
  for (const ex of runningExecs) {
    runningByWf[ex.workflowId] = (runningByWf[ex.workflowId] || 0) + 1;
  }
  const queuedIds = new Set(staticData.pipelineQueue.map(q => String(q.workflowId)));
  const qLen = staticData.pipelineQueue.length;

  const keyboard = [];

  // Optional live running alert banner button at top
  if (runningExecs.length > 0) {
    keyboard.push([
      {
        text: `⚡ ${runningExecs.length} Workflow(s) Running Now — View Live Progress`,
        callback_data: 'sys:running:0'
      }
    ]);
  }

  // ── DRAWER 1: WORKFLOWS ──────────────────────────────────────────────────
  const isWfsOpen = openSection === 'wfs';
  keyboard.push([
    {
      text: `${isWfsOpen ? '▾' : '▸'} 📁 1. Workflows (${sorted.length} Total: ${activeCount}🟢 / ${pausedCount}⚪)`,
      callback_data: isWfsOpen ? 'nav:home' : `sec:wfs:${safePage}`
    }
  ]);

  if (isWfsOpen) {
    for (const wf of slice) {
      const isRunning = runningByWf[wf.id] > 0;
      const isQueued = queuedIds.has(String(wf.id));
      const statusIcon = isRunning ? '⚡' : (isQueued ? '⏳' : (wf.active ? '🟢' : '⚪'));
      const cleanName = (wf.name || 'Untitled').slice(0, 32);
      keyboard.push([
        {
          text: `   ${statusIcon} ${cleanName}`,
          callback_data: `wf:view:${wf.id}:${safePage}`
        }
      ]);
    }
    if (totalPages > 1) {
      const navRow = [];
      if (safePage > 0) navRow.push({ text: '⬅️ Prev', callback_data: `sec:wfs:${safePage - 1}` });
      navRow.push({ text: `📄 ${safePage + 1}/${totalPages}`, callback_data: `sec:wfs:${safePage}` });
      if (safePage < totalPages - 1) navRow.push({ text: 'Next ➡️', callback_data: `sec:wfs:${safePage + 1}` });
      keyboard.push(navRow);
    }
    keyboard.push([
      { text: '   🔄 Refresh Workflows Drawer', callback_data: `sec:wfs:${safePage}` }
    ]);
  }

  // ── DRAWER 2: SCHEDULE, QUEUE & OVERLAP GUARD ────────────────────────────
  const isSchedOpen = openSection === 'sched';
  keyboard.push([
    {
      text: `${isSchedOpen ? '▾' : '▸'} 🗓️ 2. Schedule, Queue & Overlap Guard${qLen > 0 ? ` (${qLen}⏳)` : ''}`,
      callback_data: isSchedOpen ? 'nav:home' : 'sec:sched'
    }
  ]);

  if (isSchedOpen) {
    keyboard.push([
      { text: '   • 🗓️ Free Hours & Schedule Advisor', callback_data: 'cmd:schedule' }
    ]);
    keyboard.push([
      { text: '   • 🪄 Auto-Stagger Overlapping Schedules', callback_data: 'cmd:stagger' }
    ]);
    keyboard.push([
      { text: `   • 🚦 View Pipeline Queue (${qLen} waiting)`, callback_data: 'cmd:queue' }
    ]);
    keyboard.push([
      { text: `   • ⚡ Active / Running Executions (${runningExecs.length})`, callback_data: 'sys:running:0' }
    ]);
  }

  // ── DRAWER 3: SYSTEM OPS, BACKUP & CREDENTIALS ───────────────────────────
  const isOpsOpen = openSection === 'ops';
  keyboard.push([
    {
      text: `${isOpsOpen ? '▾' : '▸'} 🛠️ 3. System Ops, Backup & Credentials`,
      callback_data: isOpsOpen ? 'nav:home' : 'sec:ops'
    }
  ]);

  if (isOpsOpen) {
    keyboard.push([
      { text: '   • 💾 Sanitized Backup to GitHub', callback_data: 'cmd:backup' }
    ]);
    keyboard.push([
      { text: '   • 🔧 Auto-Wire All Workflows', callback_data: `cmd:autowire:${safePage}` }
    ]);
    keyboard.push([
      { text: '   • 🔑 Refresh Credentials & OAuth Portal', callback_data: 'cmd:creds' }
    ]);
    keyboard.push([
      { text: '   • 📖 Command Cheat Sheet (/help)', callback_data: 'cmd:help' }
    ]);
    keyboard.push([
      { text: '   • 🛑 Emergency Panic: Pause All', callback_data: `cmd:panic:${safePage}` }
    ]);
  }

  // Footer Row
  if (openSection === 'none') {
    keyboard.push([
      { text: '🔄 Refresh Dashboard Status', callback_data: 'nav:home' }
    ]);
  } else {
    keyboard.push([
      { text: '▴ Collapse All Drawers (Compact View)', callback_data: 'nav:home' }
