    sectionHint;

  return { text: body, inlineKeyboard: keyboard, parseMode: 'Markdown' };
}

// Helper: Compute live progress bar & active step for a running execution
function computeExecutionProgress(wfObj, exFull) {
  const nodes = (wfObj.nodes || []).filter(n => !String(n.type).includes('stickyNote') && !n.disabled);
  const workNodes = nodes.filter(n => !String(n.type).includes('Trigger'));
  const expectedSteps = Math.max(5, Math.round(workNodes.length * 0.68));
  const rd = exFull?.data?.resultData || {};
  const runData = rd.runData || {};
  const doneNames = Object.keys(runData);
  const doneCount = doneNames.length;
  const lastNode = rd.lastNodeExecuted || doneNames[doneNames.length - 1] || 'Starting trigger...';

  let activeNode = 'Processing next step...';
  const conns = wfObj.connections || {};
  if (lastNode && conns[lastNode]?.main) {
    const lastRuns = runData[lastNode] || [];
    const lastFinish = lastRuns.length > 0
      ? (lastRuns[lastRuns.length - 1].startTime || 0) + (lastRuns[lastRuns.length - 1].executionTime || 0)
      : 0;
    const candidates = [];
    for (const branch of conns[lastNode].main) {
      for (const target of (branch || [])) {
        if (target?.node) candidates.push(target.node);
      }
    }
    if (candidates.length > 0) {
      const unfinished = candidates.find(c => {
        const cRuns = runData[c];
        if (!cRuns || cRuns.length === 0) return true;
        const cStart = cRuns[cRuns.length - 1].startTime || 0;
        return cStart < lastFinish;
      });
      activeNode = unfinished || candidates[0];
    }
  }

  let loopInfo = '';
  for (const [k, v] of Object.entries(runData)) {
    if (k.toLowerCase().includes('loop over') && Array.isArray(v) && v.length > 0) {
      loopInfo = `🔁 *Loop Batch:* Row/Iteration #${v.length}\n`;
      break;
    }
  }

  let pct = 10;
  if (doneCount <= 3) {
    pct = Math.min(25, 8 + doneCount * 6);
  } else {
    pct = Math.min(95, Math.max(25, Math.round((doneCount / expectedSteps) * 100)));
  }
  const filled = Math.max(1, Math.min(10, Math.round(pct / 10)));
  const bar = '█'.repeat(filled) + '░'.repeat(10 - filled);
  const startMs = exFull?.startedAt ? new Date(exFull.startedAt).getTime() : Date.now();
  const elapsedSec = Math.max(1, Math.round((Date.now() - startMs) / 1000));

  return {
    pct,
    bar,
    doneCount,
    expectedSteps,
    lastNode,
    activeNode,
    loopInfo,
    elapsedSec
  };
}

// Helper: Build Single Workflow Control Card
function buildWorkflowCard(wf, runningExecs, page = 0, bannerMsg = '', liveProg = null) {
  const wfRunning = runningExecs.filter(e => String(e.workflowId) === String(wf.id));
  const queueIdx = staticData.pipelineQueue.findIndex(q => String(q.workflowId) === String(wf.id));
  const nodes = wf.nodes || [];
  const hasSchedule = nodes.some(n => n.type === 'n8n-nodes-base.scheduleTrigger');
  const hasSubTrigger = nodes.some(n => n.type === 'n8n-nodes-base.executeWorkflowTrigger');
  const hasErrorLinked = wf.settings?.errorWorkflow === cfg.MASTER_WORKFLOW_ID;
  const schedInfo = analyzeWorkflowSchedule(wf, 2.5);

  const statusBadge = wf.active ? '🟢 PUBLISHED (Active)' : '⚪ UNPUBLISHED (Paused)';
  const runBadge = wfRunning.length > 0
    ? `⚡ ${wfRunning.length} Execution(s) Running`
    : (queueIdx >= 0 ? `⏳ Queued in Pipeline (#${queueIdx + 1})` : '💤 Idle');
  const wireBadge = (hasSubTrigger && hasErrorLinked) ? '✅ Fully Wired' : '⚠️ Needs Auto-Wire';

  const keyboard = [
    wfRunning.length > 0
      ? [
          { text: '📡 Live Stream Progress', callback_data: `wf:track:${wf.id}:${page}` },
          { text: '🔄 Refresh Progress', callback_data: `wf:view:${wf.id}:${page}` }
        ]
      : [
          { text: '▶️ Execute Now (Live Progress)', callback_data: `wf:exec:${wf.id}:${page}` }
        ],
    [
      wf.active
        ? { text: '⏸️ Pause / Unpublish Workflow', callback_data: `wf:off:${wf.id}:${page}` }
        : { text: '🚀 Publish / Activate Workflow', callback_data: `wf:on:${wf.id}:${page}` }
    ]
  ];

  if (hasSchedule) {
    keyboard.push([
      { text: '⏱️ Shift Schedule +15m', callback_data: `wf:shift:${wf.id}:15` },
      { text: '⏱️ Shift Schedule +30m', callback_data: `wf:shift:${wf.id}:30` }
    ]);
  }

  keyboard.push([
    { text: '🛑 Stop Running Execution', callback_data: `wf:stop:${wf.id}:${page}` },
    { text: '🔧 Auto-Wire', callback_data: `wf:wire:${wf.id}:${page}` }
  ]);

  keyboard.push([
    { text: '🔄 Refresh Card', callback_data: `wf:view:${wf.id}:${page}` },
    { text: '📂 Workflows Drawer', callback_data: `sec:wfs:${page}` }
  ]);
  keyboard.push([
    { text: '▴ Back to Compact Menu', callback_data: 'nav:home' }
  ]);

  const progSection = liveProg
    ? `\n📊 *Live Progress:* \`[${liveProg.bar}] ${liveProg.pct}%\` (${liveProg.doneCount} steps done)\n` +
      liveProg.loopInfo +
      `⚙️ *Running Now:* \`${liveProg.activeNode}\`\n` +
      `✅ *Last Completed:* \`${liveProg.lastNode}\`\n` +
      `⏱️ *Elapsed:* \`${liveProg.elapsedSec}s\` (Exec \`#${wfRunning[0]?.id}\`)\n`
    : '';
  const header = bannerMsg ? `${bannerMsg}\n\n` : '';
  const body =
    `${header}⚙️ *Workflow Control Card*\n` +
    `━━━━━━━━━━━━━━━━━━━━\n` +
    `📌 *Name:* \`${wf.name}\`\n` +
    `🆔 *ID:* \`${wf.id}\`\n` +
    `📡 *Status:* ${statusBadge}\n` +
    `🏃 *Execution:* ${runBadge}\n` +
    progSection +
    `⏰ *Schedule:* ${schedInfo.summary}\n` +
    `⚖️ *Resource Load:* ${schedInfo.weight}\n` +
    `🛡️ *Telegram & Error Guard:* ${wireBadge}`;

  return { text: body, inlineKeyboard: keyboard, parseMode: 'Markdown' };
}

