// Helper: Build Credentials & OAuth Refresh Portal Card
function buildCredsCard(allWorkflows) {
  const pubUrl = (cfg.N8N_PUBLIC_URL || 'https://your-n8n-domain.example.com').replace(/\/+$/, '');
  const credMap = {};
  for (const w of allWorkflows) {
    if (String(w.id) === String(cfg.MASTER_WORKFLOW_ID)) continue;
    for (const n of (w.nodes || [])) {
      for (const [cType, cObj] of Object.entries(n.credentials || {})) {
        const key = `${cObj?.name || cType} (${cType})`;
        if (!credMap[key]) credMap[key] = new Set();
        credMap[key].add(w.name);
      }
    }
  }
  const lines = Object.entries(credMap).map(([k, set]) => `• *${k}*\n  _Used by:_ ${Array.from(set).map(x => '\`' + x.slice(0, 28) + '\`').join(', ')}`);
  return {
    text:
      `🔑 *n8n Credentials & OAuth Refresh Portal*\n` +
      `━━━━━━━━━━━━━━━━━━━━\n` +
      (lines.length > 0 ? lines.join('\n\n') : 'No external credentials detected.') +
      `\n\n💡 *Tip:* Tap the button below to open your n8n Credentials page and reconnect any expired OAuth token (e.g. Google Sheets / Drive):`,
    parseMode: 'Markdown',
    inlineKeyboard: [
      [{ text: '🔑 Open n8n Credentials Page', url: `${pubUrl}/home/credentials` }],
      [
        { text: '📂 System Ops Drawer', callback_data: 'sec:ops' },
        { text: '▴ Back to Compact Menu', callback_data: 'nav:home' }
      ]
    ]
  };
}

