// Route Commands & Callbacks
let toastText = '';
let uiResponse = null;

try {
  if (isCallback) {
    const parts = cbData.split(':');
    const namespace = parts[0];
    const action = parts[1];

    if (namespace === 'nav' || (namespace === 'sec' && action === 'none')) {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      uiResponse = buildMainMenu(allWorkflows, runningExecs, 0, '', 'none');
      toastText = '🎛️ Compact Menu';
    } else if (namespace === 'sec') {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      if (action === 'wfs') {
        const page = parseInt(parts[2] || '0', 10);
        uiResponse = buildMainMenu(allWorkflows, runningExecs, page, '', 'wfs');
        toastText = '📁 Workflows Drawer';
      } else if (action === 'sched') {
        uiResponse = buildMainMenu(allWorkflows, runningExecs, 0, '', 'sched');
        toastText = '🗓️ Schedule & Queue Drawer';
      } else if (action === 'ops') {
        uiResponse = buildMainMenu(allWorkflows, runningExecs, 0, '', 'ops');
        toastText = '🛠️ System Ops Drawer';
      } else {
        uiResponse = buildMainMenu(allWorkflows, runningExecs, 0, '', 'none');
      }
    } else if (namespace === 'sys' && action === 'running') {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      uiResponse = buildRunningExecsCard(runningExecs, allWorkflows);
      toastText = `⚡ ${runningExecs.length} running execution(s)`;
    } else if (namespace === 'cmd') {
      if (action === 'list') {
        const page = parseInt(parts[2] || '0', 10);
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        uiResponse = buildMainMenu(allWorkflows, runningExecs, page, '', 'wfs');
        toastText = '📁 Workflows list refreshed';
      } else if (action === 'schedule') {
        const { allWorkflows, recentExecs } = await fetchAllState.call(this, true);
        uiResponse = buildScheduleAdvisorReport(allWorkflows, recentExecs);
        toastText = '🗓️ Schedule Advisor updated';
      } else if (action === 'stagger') {
        const { allWorkflows, recentExecs } = await fetchAllState.call(this, true);
        const shifted = await autoStaggerAllSchedules.call(this, allWorkflows);
        const refreshed = await fetchAllState.call(this, false);
        const msg = shifted.length > 0
          ? `🪄 *Auto-Staggered ${shifted.length} Workflow(s) to Prevent Overlaps:*\n${shifted.join('\n')}`
          : `✅ All scheduled workflows are already staggered on distinct minute offsets!`;
        uiResponse = buildScheduleAdvisorReport(refreshed.allWorkflows, recentExecs, msg);
        toastText = `🪄 Staggered ${shifted.length} workflow(s)!`;
      } else if (action === 'queue') {
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        uiResponse = buildQueueCard(runningExecs, allWorkflows);
        toastText = '🚦 Pipeline queue refreshed';
      } else if (action === 'qclear') {
        staticData.pipelineQueue = [];
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        uiResponse = buildQueueCard(runningExecs, allWorkflows, '🗑️ *Cleared all waiting items from the Pipeline Queue.*');
        toastText = '🗑️ Queue cleared';
      } else if (action === 'qpop') {
        if (staticData.pipelineQueue.length > 0) {
          const nextItem = staticData.pipelineQueue.shift();
          const wireRes = await autoWireWorkflow.call(this, { id: nextItem.workflowId });
          return [{
            json: {
              _config: cfg,
              chatId,
              messageId,
              callbackQueryId,
              toastText: `🚀 Launching ${wireRes.wf.name} from queue...`,
              shouldExecuteSubworkflow: true,
              targetWorkflowId: wireRes.wf.id,
              targetWorkflowName: wireRes.wf.name,
              returnPage: 0,
              launchStartedAt: Date.now()
            }
          }];
        }
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        uiResponse = buildQueueCard(runningExecs, allWorkflows, 'ℹ️ Pipeline queue is already empty.');
      } else if (action === 'autowire') {
        const page = parseInt(parts[2] || '0', 10);
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        let wiredCount = 0;
        for (const w of allWorkflows) {
          try {
            const res = await autoWireWorkflow.call(this, w);
            if (res.changed) wiredCount++;
          } catch (e) {}
        }
        uiResponse = buildMainMenu(
          allWorkflows,
          runningExecs,
          page,
          `🔧 *Auto-Wire Complete:* Updated *${wiredCount}* workflow(s) with On-Demand Telegram Trigger & Error Circuit Breaker!`,
          'ops'
        );
        toastText = `✅ Wired ${wiredCount} workflow(s)!`;
      } else if (action === 'creds') {
        const { allWorkflows } = await fetchAllState.call(this, false);
        uiResponse = buildCredsCard(allWorkflows);
        toastText = '🔑 Credentials Portal';
      } else if (action === 'help') {
        uiResponse = buildHelpCard();
        toastText = '📖 Command Cheat Sheet';
      } else if (action === 'panic') {
        const page = parseInt(parts[2] || '0', 10);
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        let paused = 0;
        for (const w of allWorkflows) {
          if (w.active && String(w.id) !== String(cfg.MASTER_WORKFLOW_ID)) {
            await apiRequest(this, {
              method: 'POST',
              url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${w.id}/deactivate`,
              headers: n8nHeaders
            });
            w.active = false;
            paused++;
          }
        }
        staticData.pipelineQueue = [];
        uiResponse = buildMainMenu(
          allWorkflows,
          runningExecs,
          page,
          `🛑 *Emergency Panic Executed:* Paused *${paused}* active workflow(s) & cleared queue.`,
          'ops'
        );
        toastText = `🛑 Paused ${paused} workflows!`;
      }
    } else if (namespace === 'wf') {
      const wfId = parts[2];
      const page = parseInt(parts[3] || '0', 10);

      if (action === 'view') {
        const wf = await apiRequest(this, {
          method: 'GET',
          url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wfId}`,
          headers: n8nHeaders
        });
        const { runningExecs } = await fetchAllState.call(this, false);
        const wfRun = runningExecs.find(e => String(e.workflowId) === String(wf.id));
        let liveProg = null;
        if (wfRun) {
          try {
            const exFull = await apiRequest(this, {
              method: 'GET',
              url: `${cfg.N8N_BASE_URL}/api/v1/executions/${wfRun.id}?includeData=true`,
              headers: n8nHeaders
            });
            liveProg = computeExecutionProgress(wf, exFull);
          } catch (e) {}
        }
        uiResponse = buildWorkflowCard(wf, runningExecs, page, '', liveProg);
      } else if (action === 'shift') {
        const deltaMins = parseInt(parts[3] || '15', 10);
        const shiftRes = await shiftWorkflowSchedule.call(this, wfId, deltaMins);
        const { runningExecs } = await fetchAllState.call(this, false);
        uiResponse = buildWorkflowCard(
          shiftRes.wf,
          runningExecs,
          0,
          `⏱️ *Schedule Updated!* Shifted \`${shiftRes.wf.name}\` by +${deltaMins}m (${shiftRes.newDesc}) to prevent overlap.`
        );
        toastText = `⏱️ Shifted schedule +${deltaMins}m!`;
      } else if (action === 'on' || action === 'off') {
        const endpoint = action === 'on' ? 'activate' : 'deactivate';
        const wf = await apiRequest(this, {
          method: 'POST',
          url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wfId}/${endpoint}`,
          headers: n8nHeaders
        });
        const { runningExecs } = await fetchAllState.call(this, false);
        const banner = action === 'on'
          ? `✅ *Published & Activated:* \`${wf.name}\``
          : `⏸️ *Paused & Unpublished:* \`${wf.name}\``;
        uiResponse = buildWorkflowCard(wf, runningExecs, page, banner);
        toastText = action === 'on' ? '🚀 Workflow Published!' : '⏸️ Workflow Paused!';
      } else if (action === 'stop') {
        const { runningExecs } = await fetchAllState.call(this, false);
        const targetExecs = runningExecs.filter(e => String(e.workflowId) === String(wfId));
        let stopped = 0;
        for (const ex of targetExecs) {
          try {
            staticData.intentionallyStoppedExecs[String(ex.id)] = Date.now();
            await apiRequest(this, {
              method: 'POST',
              url: `${cfg.N8N_BASE_URL}/api/v1/executions/${ex.id}/stop`,
              headers: n8nHeaders
            });
            stopped++;
          } catch (e) {}
        }
        staticData.pipelineQueue = staticData.pipelineQueue.filter(q => String(q.workflowId) !== String(wfId));
        const wf = await apiRequest(this, {
          method: 'GET',
          url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${wfId}`,
          headers: n8nHeaders
        });
        const banner = stopped > 0
          ? `🛑 *Stopped ${stopped} running execution(s)* for \`${wf.name}\`.`
          : `ℹ️ No active executions were running for \`${wf.name}\` (removed if queued).`;
        uiResponse = buildWorkflowCard(wf, [], page, banner);
        toastText = stopped > 0 ? `🛑 Stopped ${stopped} run(s)` : 'ℹ️ Stopped / Unqueued';
      } else if (action === 'wire') {
        const res = await autoWireWorkflow.call(this, { id: wfId });
        const { runningExecs } = await fetchAllState.call(this, false);
        uiResponse = buildWorkflowCard(
          res.wf,
          runningExecs,
          page,
          `🔧 *Auto-Wired:* Added On-Demand Trigger & linked Error Handler!`
        );
        toastText = '🔧 Workflow wired!';
      } else if (action === 'resume_all') {
        const depCsv = parts[3] || '';
        const savedGroup = staticData.lastPausedGroup?.[wfId] || [];
        const idsToResume = Array.from(new Set([wfId, ...savedGroup, ...depCsv.split(',').filter(Boolean)]));
        const resumedNames = [];
        for (const id of idsToResume) {
          try {
            const w = await apiRequest(this, {
              method: 'POST',
              url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${id}/activate`,
              headers: n8nHeaders
            });
            resumedNames.push(w.name || id);
          } catch (e) {}
        }
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        uiResponse = buildMainMenu(
          allWorkflows,
          runningExecs,
          0,
          `✅ *Circuit Breaker Reset!* Re-enabled *${resumedNames.length}* workflow(s):\n• ${resumedNames.join('\n• ')}`,
          'wfs'
        );
        toastText = `✅ Re-enabled ${resumedNames.length} workflow(s)!`;
      } else if (action === 'exec' || action === 'force_exec' || action === 'track') {
        const wireRes = await autoWireWorkflow.call(this, { id: wfId });
        const wf = wireRes.wf;
        const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
        const alreadyRunningThisWf = runningExecs.find(e => String(e.workflowId) === String(wf.id));

        // OVERLAP PROTECTION: Check if another workflow is currently running!
        if (action === 'exec' && !alreadyRunningThisWf && runningExecs.length >= cfg.MAX_CONCURRENT_WORKFLOWS) {
          const runningNames = runningExecs.map(re => {
            const found = allWorkflows.find(w => String(w.id) === String(re.workflowId));
            return found ? found.name : `Workflow #${re.workflowId}`;
          });
          const alreadyQueued = staticData.pipelineQueue.some(q => String(q.workflowId) === String(wf.id));
          if (!alreadyQueued) {
            staticData.pipelineQueue.push({
              workflowId: wf.id,
              workflowName: wf.name,
              queuedAt: new Date().toISOString(),
              reason: `Queued behind ${runningNames[0]}`
            });
          }
          const pos = staticData.pipelineQueue.findIndex(q => String(q.workflowId) === String(wf.id)) + 1;
          const overlapBanner =
            `🚦 *Overlap Protection Triggered!*\n` +
            `⚡ \`${runningNames.join(', ')}\` is currently running and hasn't finished yet.\n\n` +
            `⏳ Put *\`${wf.name}\`* into the **Pipeline Queue (Position #${pos})** — it will automatically execute as soon as the current workflow finishes so your server doesn't crash!`;

          const card = buildWorkflowCard(wf, runningExecs, page, overlapBanner);
          card.inlineKeyboard.unshift([
            { text: '⚡ Force Run Immediately Anyway', callback_data: `wf:force_exec:${wf.id}:${page}` },
            { text: `🚦 View Queue (${staticData.pipelineQueue.length})`, callback_data: 'cmd:queue' }
          ]);
          uiResponse = card;
          toastText = `⏳ Added to Pipeline Queue (#${pos})!`;
        } else {
          staticData.pipelineQueue = staticData.pipelineQueue.filter(q => String(q.workflowId) !== String(wf.id));
          const isTrackOnly = Boolean(action === 'track' || alreadyRunningThisWf);
          const tgBase = `https://api.telegram.org/bot${cfg.TELEGRAM_BOT_TOKEN}`;

          // 1. Immediately answer callback query so Telegram button spinner stops right away
          if (callbackQueryId) {
            try {
              await apiRequest(this, {
                method: 'POST',
                url: `${tgBase}/answerCallbackQuery`,
                body: {
                  callback_query_id: callbackQueryId,
                  text: isTrackOnly ? '📡 Attaching live progress tracker...' : `🚀 Launching ${wf.name}...`
                }
              });
            } catch (e) {}
          }

          // 2. Immediately display the initial Live Progress Bar card on Telegram BEFORE execution starts
          const initText =
            `⚡ *WORKFLOW RUNNING (LIVE PROGRESS)*\n` +
            `━━━━━━━━━━━━━━━━━━━━\n` +
            `📌 *Workflow:* \`${wf.name}\`\n` +
            `📊 *Progress:* \`[█░░░░░░░░░] 8%\`\n` +
            `⚙️ *Current Step:* \`${isTrackOnly ? 'Fetching active execution state...' : 'Initializing trigger & starting nodes...'}\`\n` +
            `⏱️ *Elapsed:* \`0s\`\n\n` +
            `📡 _Auto-updating live every 3s..._`;
          const initKb = {
            inline_keyboard: [
              [
                { text: '🔄 Refresh Status', callback_data: `wf:view:${wf.id}:${page}` },
                { text: '🛑 Stop Execution', callback_data: `wf:stop:${wf.id}:${page}` }
              ],
              [
                { text: '📂 Workflows Drawer', callback_data: `sec:wfs:${page}` },
                { text: '▴ Compact Menu', callback_data: 'nav:home' }
              ]
            ]
          };

          let liveMessageId = messageId;
          try {
            if (liveMessageId) {
              await apiRequest(this, {
                method: 'POST',
                url: `${tgBase}/editMessageText`,
                body: {
                  chat_id: chatId,
                  message_id: liveMessageId,
                  text: initText,
                  parse_mode: 'Markdown',
                  reply_markup: initKb
                }
              });
            } else {
              const sent = await apiRequest(this, {
                method: 'POST',
                url: `${tgBase}/sendMessage`,
                body: {
                  chat_id: chatId,
                  text: initText,
                  parse_mode: 'Markdown',
                  reply_markup: initKb
                }
              });
              liveMessageId = sent?.result?.message_id || null;
            }
          } catch (e) {}

          return [{
            json: {
              _config: cfg,
              chatId,
              messageId: liveMessageId,
              callbackQueryId: null,
              toastText: null,
              shouldExecuteSubworkflow: !isTrackOnly,
              shouldTrackRunningOnly: isTrackOnly,
              trackedExecId: alreadyRunningThisWf ? alreadyRunningThisWf.id : null,
              targetWorkflowId: wf.id,
              targetWorkflowName: wf.name,
              returnPage: page,
              launchStartedAt: Date.now()
            }
          }];
        }
      }
    }
  } else {
    // 2. Handle Text Commands & Natural Language Questions
    const lowerText = text.toLowerCase();
    if (
      lowerText.startsWith('/schedule') ||
      lowerText.startsWith('/free') ||
      lowerText.startsWith('/slots') ||
      lowerText.includes('free hour') ||
      lowerText.includes('good time') ||
      lowerText.includes('when to schedule') ||
      lowerText.includes('when will be') ||
      lowerText.includes('overlap') ||
      lowerText.includes('schedule another')
    ) {
      const { allWorkflows, recentExecs } = await fetchAllState.call(this, true);
      uiResponse = buildScheduleAdvisorReport(allWorkflows, recentExecs);
    } else if (lowerText.startsWith('/queue') || lowerText.startsWith('/pipeline')) {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      uiResponse = buildQueueCard(runningExecs, allWorkflows);
    } else if (lowerText.startsWith('/running')) {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      uiResponse = buildRunningExecsCard(runningExecs, allWorkflows);
    } else if (lowerText.startsWith('/stagger')) {
      const { allWorkflows, recentExecs } = await fetchAllState.call(this, true);
      const shifted = await autoStaggerAllSchedules.call(this, allWorkflows);
      const refreshed = await fetchAllState.call(this, false);
      uiResponse = buildScheduleAdvisorReport(
        refreshed.allWorkflows,
        recentExecs,
        `🪄 *Auto-Staggered ${shifted.length} Workflow(s):*\n${shifted.join('\n')}`
      );
    } else if (lowerText.startsWith('/creds') || lowerText.includes('credential') || lowerText.includes('refresh token')) {
      const { allWorkflows } = await fetchAllState.call(this, false);
      uiResponse = buildCredsCard(allWorkflows);
    } else if (lowerText.startsWith('/help') || lowerText === 'help') {
      uiResponse = buildHelpCard();
    } else if (lowerText.startsWith('/autowire')) {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      let wiredCount = 0;
      for (const w of allWorkflows) {
        try {
          const res = await autoWireWorkflow.call(this, w);
          if (res.changed) wiredCount++;
        } catch (e) {}
      }
      uiResponse = buildMainMenu(
        allWorkflows,
        runningExecs,
        0,
        `🔧 *Auto-Wired ${wiredCount} workflow(s)* for On-Demand Telegram Execution & Error Protection!`,
        'ops'
      );
    } else if (lowerText.startsWith('/list') || lowerText.startsWith('/workflows')) {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      uiResponse = buildMainMenu(allWorkflows, runningExecs, 0, '', 'wfs');
    } else {
      const { allWorkflows, runningExecs } = await fetchAllState.call(this, false);
      uiResponse = buildMainMenu(allWorkflows, runningExecs, 0, '', 'none');
    }
  }
} catch (err) {
  uiResponse = {
    text: `❌ *n8n Manager API Error*\n\`${err.message}\`\n\nPlease verify \`N8N_API_KEY\` and \`N8N_BASE_URL\` in the *⚙️ Master Config* node.`,
    parseMode: 'Markdown',
    inlineKeyboard: [[{ text: '🔄 Retry Compact Menu', callback_data: 'nav:home' }]]
  };
}

return [{
  json: {
    _config: cfg,
    chatId,
    messageId,
    callbackQueryId,
    toastText,
    shouldExecuteSubworkflow: false,
    telegramResponse: uiResponse
  }
}];

// ============================================================================
// 📡 LIVE PROGRESS STREAMER & FINAL RESULT FORMATTER
// Polls running child execution every 3s, updates Telegram progress bar live,
// and renders final 100% completion card when finished.
// ============================================================================
const inputItem = $input.first()?.json || {};
let state = inputItem._isProgressLoop ? { ...inputItem } : null;

if (!state) {
  let ctrl = {};
  try {
    if ($('📱 Telegram Bot Controller').isExecuted) {
      ctrl = $('📱 Telegram Bot Controller').first().json;
    } else if ($('🚦 Overlap Watchdog & Pipeline Runner').isExecuted) {
      ctrl = $('🚦 Overlap Watchdog & Pipeline Runner').first().json;
    }
  } catch (e) {}
  const cfg = ctrl._config || $('⚙️ Master Config (Edit Here)').first().json._config;
  state = {
    _isProgressLoop: true,
    _config: cfg,
    chatId: ctrl.chatId || cfg.ADMIN_CHAT_ID,
    messageId: ctrl.messageId || null,
    targetWorkflowId: ctrl.targetWorkflowId,
    targetWorkflowName: ctrl.targetWorkflowName || 'Workflow',
    returnPage: ctrl.returnPage || 0,
    launchStartedAt: ctrl.launchStartedAt || (Date.now() - 2000),
    trackedExecId: ctrl.trackedExecId || null,
    pollCount: 0,
    lastRenderedText: '',
    wfMeta: null
  };
}

const cfg = state._config;
const n8nHeaders = { 'X-N8N-API-KEY': cfg.N8N_API_KEY };
const tgBase = `https://api.telegram.org/bot${cfg.TELEGRAM_BOT_TOKEN}`;
state.pollCount = (state.pollCount || 0) + 1;

async function apiRequest(ctx, opts) {
  if (ctx && ctx.helpers && typeof ctx.helpers.httpRequest === 'function') {
    return await ctx.helpers.httpRequest({
      method: opts.method || 'GET',
      url: opts.url,
      headers: opts.headers || {},
      body: opts.body,
      json: true,
    });
  }
  const fetchOpts = {
    method: opts.method || 'GET',
    headers: {
      'Accept': 'application/json',
      ...(opts.body ? { 'Content-Type': 'application/json' } : {}),
      ...(opts.headers || {}),
    },
  };
  if (opts.body !== undefined) {
    fetchOpts.body = typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body);
  }
  const res = await fetch(opts.url, fetchOpts);
  const text = await res.text();
  let data;
  try { data = text ? JSON.parse(text) : {}; } catch (e) { data = { raw: text }; }
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${typeof data === 'object' ? JSON.stringify(data) : text}`);
  }
  return data;
}

// 1. Fetch & cache target workflow metadata (node count + connections) on Tick 1
if (!state.wfMeta && state.targetWorkflowId) {
  try {
    const wfObj = await apiRequest(this, {
      method: 'GET',
      url: `${cfg.N8N_BASE_URL}/api/v1/workflows/${state.targetWorkflowId}`,
      headers: n8nHeaders
    });
    const nodes = (wfObj.nodes || []).filter(n => !String(n.type).includes('stickyNote') && !n.disabled);
    const workNodes = nodes.filter(n => !String(n.type).includes('Trigger'));
    state.wfMeta = {
      expectedSteps: Math.max(5, Math.round(workNodes.length * 0.68)),
      connections: wfObj.connections || {}
    };
  } catch (e) {
    state.wfMeta = { expectedSteps: 18, connections: {} };
  }
}

// 2. Discover or fetch the child execution
let exFull = null;
try {
  if (!state.trackedExecId) {
    const listRes = await apiRequest(this, {
      method: 'GET',
      url: `${cfg.N8N_BASE_URL}/api/v1/executions?workflowId=${state.targetWorkflowId}&limit=5`,
      headers: n8nHeaders
    });
    const execs = listRes.data || [];
    const activeEx = execs.find(e => e.status === 'running' || e.status === 'waiting');
    if (activeEx) {
      state.trackedExecId = activeEx.id;
    } else if (execs.length > 0) {
      const latest = execs[0];
      const latestStart = latest.startedAt ? new Date(latest.startedAt).getTime() : 0;
      if (latestStart >= state.launchStartedAt - 15000) {
        state.trackedExecId = latest.id;
      }
    }
  }
  if (state.trackedExecId) {
    exFull = await apiRequest(this, {
      method: 'GET',
      url: `${cfg.N8N_BASE_URL}/api/v1/executions/${state.trackedExecId}?includeData=true`,
      headers: n8nHeaders
    });
  }
} catch (e) {}

const status = exFull?.status || (state.pollCount <= 2 ? 'running' : 'unknown');
const rd = exFull?.data?.resultData || {};
const runData = rd.runData || {};
const doneNames = Object.keys(runData);
const doneCount = doneNames.length;
const lastNode = rd.lastNodeExecuted || doneNames[doneNames.length - 1] || 'Initializing trigger...';
const expectedSteps = state.wfMeta?.expectedSteps || 18;
const startMs = exFull?.startedAt ? new Date(exFull.startedAt).getTime() : state.launchStartedAt;
const stopMs = exFull?.stoppedAt ? new Date(exFull.stoppedAt).getTime() : Date.now();
const elapsedSec = Math.max(1, Math.round(((exFull?.stoppedAt ? stopMs : Date.now()) - startMs) / 1000));

// Determine next node currently executing
let activeNode = 'Processing step...';
const conns = state.wfMeta?.connections || {};
if (lastNode && conns[lastNode]?.main) {
  const lastRuns = runData[lastNode] || [];
  const lastFinish = lastRuns.length > 0
    ? (lastRuns[lastRuns.length - 1].startTime || 0) + (lastRuns[lastRuns.length - 1].executionTime || 0)
    : 0;
  const candidates = [];
  for (const branch of conns[lastNode].main) {
    for (const target of (branch || [])) {
      if (target?.node) candidates.push(target.node);
    }
  }
  if (candidates.length > 0) {
    const unfinished = candidates.find(c => {
      const cRuns = runData[c];
      if (!cRuns || cRuns.length === 0) return true;
      const cStart = cRuns[cRuns.length - 1].startTime || 0;
      return cStart < lastFinish;
    });
    activeNode = unfinished || candidates[0];
  }
}

let loopLine = '';
