function extractResources(wf) {
  const resources = { sheets: new Set(), supabaseTables: new Set(), subWorkflows: new Set(), prefix: '' };
  const name = wf.name || '';
  const prefixMatch = name.match(/^([A-Za-z0-9]+)[_\s-]+/);
