    const docId = p.documentId?.value || (typeof p.documentId === 'string' ? p.documentId : null);
    if (docId && docId.length > 15 && !docId.includes('YOUR_')) resources.sheets.add(docId);
    if (p.tableId && typeof p.tableId === 'string') resources.supabaseTables.add(p.tableId);
    const subId = p.workflowId?.value || (typeof p.workflowId === 'string' ? p.workflowId : null);
    if (subId) resources.subWorkflows.add(String(subId));
  }
  return resources;
}

